const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const arizona = ee.FeatureCollection('TIGER/2018/States')
        .filter(ee.Filter.eq('NAME', 'Arizona'))
        .geometry();

    const targetDateStart = '2017-07-15';
    const targetDateEnd = '2017-07-21';

    const baselineYearStart = 2001;
    const baselineYearEnd = 2010;
    const dayOfYearStart = ee.Date(targetDateStart).getRelative('day', 'year');
    const dayOfYearEnd = ee.Date(targetDateEnd).getRelative('day', 'year');

    // 2. Data Acquisition
    const modisLst = ee.ImageCollection('MODIS/061/MYD11A1').select(['LST_Day_1km', 'QC_Day']);

    // Function to mask low-quality pixels and convert to Celsius
    const processModis = function(image) {
        const quality = image.select('QC_Day');
        // Bits 0-1 are mandatory QA flags. '00' is good quality.
        const qaMask = quality.bitwiseAnd(3).eq(0);
        const lstCelsius = image.select('LST_Day_1km')
            .multiply(0.02) // Apply scale factor
            .subtract(273.15) // Convert from Kelvin to Celsius
            .rename('LST_Celsius');
        return lstCelsius.updateMask(qaMask);
    };

    // 3. Processing
    // --- Target Period (2017) ---
    const collection2017 = modisLst.filterDate(targetDateStart, targetDateEnd).map(processModis);
    const collection2017Size = collection2017.size().getInfo();
    if (collection2017Size === 0) {
        console.log('Evidence: No images found for the 2017 period.');
        console.log('A: Yes'); // Placeholder for final line
        console.log('B: No'); // Placeholder for final line
        console.log('C1: Empty Collection');
        console.log('C2: No Valid Pixels');
        console.log('C3: Calculation Failure');
        console.log('D: Error');
        console.log('C1');
        return;
    }
    const image2017 = collection2017.mean();

    // --- Baseline Period (2001-2010) ---
    const baselineCollection = modisLst
        .filter(ee.Filter.calendarRange(baselineYearStart, baselineYearEnd, 'year'))
        .filter(ee.Filter.calendarRange(dayOfYearStart, dayOfYearEnd, 'day_of_year'))
        .map(processModis);
    const baselineCollectionSize = baselineCollection.size().getInfo();
    if (baselineCollectionSize === 0) {
        console.log('Evidence: No images found for the baseline 2001-2010 period.');
        console.log('A: Yes'); // Placeholder for final line
        console.log('B: No'); // Placeholder for final line
        console.log('C1: Empty Collection');
        console.log('C2: No Valid Pixels');
        console.log('C3: Calculation Failure');
        console.log('D: Error');
        console.log('C1');
        return;
    }
    const baselineImage = baselineCollection.mean();

    // 4. Calculation
    const reducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats2017 = image2017.reduceRegion({
        reducer: reducer,
        geometry: arizona,
        scale: 1000,
        maxPixels: 1e9
    }).getInfo();

    const statsBaseline = baselineImage.reduceRegion({
        reducer: reducer,
        geometry: arizona,
        scale: 1000,
        maxPixels: 1e9
    }).getInfo();

    const temp2017 = stats2017['LST_Celsius_mean'];
    const pixels2017 = stats2017['LST_Celsius_count'];

    const tempBaseline = statsBaseline['LST_Celsius_mean'];
    const pixelsBaseline = statsBaseline['LST_Celsius_count'];

    // 5. Validation & Final Answer
    console.log(`Evidence: 2017 Collection Size: ${collection2017Size}`);
    console.log(`Evidence: Baseline Collection Size: ${baselineCollectionSize}`);

    if (pixels2017 === 0 || pixelsBaseline === 0) {
        console.log(`Evidence: 2017 Valid Pixel Count: ${pixels2017}`);
        console.log(`Evidence: Baseline Valid Pixel Count: ${pixelsBaseline}`);
        console.log('C2');
        return;
    }

    if (temp2017 === null || tempBaseline === null || temp2017 === undefined || tempBaseline === undefined) {
        console.log('Evidence: Calculation returned null.');
        console.log('C3');
        return;
    }

    console.log(`Evidence: 2017 Avg LST (C): ${temp2017.toFixed(2)} (Pixels: ${pixels2017})`);
    console.log(`Evidence: 2001-2010 Avg LST (C): ${tempBaseline.toFixed(2)} (Pixels: ${pixelsBaseline})`);

    if (temp2017 > tempBaseline) {
        console.log('A');
    } else {
        console.log('B');
    }

}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
